#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Issue #16: check the undocumented Cloudflare behaviours on a real account.
# Creates only "ck16-" resources and removes them in the last stage.
# Values go to spike/cloudflare-checks/.env (gitignored); results go to
# spike/cloudflare-checks/results/results.json (gitignored).

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")"
# shellcheck source=lib/checks.sh
source ./lib/checks.sh
# Re-runs pick up everything saved last time.
# shellcheck source=/dev/null
[[ -f "$ENV_FILE" ]] && { set -a; source "./$ENV_FILE"; set +a; }

TOTAL_STAGES=14

banner "Cloudflare checks for issue #16"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
for cmd in node npm npx jq curl xargs; do
  command -v "$cmd" >/dev/null 2>&1 || { warn "missing: $cmd. Install it and re-run."; exit 1; }
done
say "Installing the pinned Wrangler for this spike..."
npm install --no-fund --no-audit --silent
note "wrangler $(npx --no-install wrangler --version 2>/dev/null | tail -n1)"
if [[ ! -s "$RESULTS" ]]; then
  ck_init_results
  record check6 "skipped" '"Not run by choice: hitting the daily cap would stop every Worker on the real account until 00:00 UTC."'
fi
ck_init_results
say ""
say "This runs on your existing Cloudflare account and your spare domain."
say "Everything it creates is named ck16-*, and stage 14 deletes it again."
note "Not run: check 6 (daily request cap). It would stop your real Workers for the day."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign Wrangler in to Cloudflare"
if wr whoami --json >/dev/null 2>&1; then
  note "Wrangler is already signed in."
else
  say "A browser tab will ask you to allow Wrangler. Approve it, then come back."
  wr login
fi
wr whoami 2>/dev/null | sed -n '/Account Name/,$p' || true
step "Copy the Account ID of the account that holds your spare domain."
note "It's also in the dashboard URL: dash.cloudflare.com/<account id>/..."
ask CK_ACCOUNT_ID "Account ID:"
write_env CK_ACCOUNT_ID "$CK_ACCOUNT_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "API token for the Access checks"
say "Wrangler handles deploys. The Access API calls need their own token."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token. Name it ck16-checks."
step "Permissions (all 'Account' rows):"
note "    Access: Apps and Policies → Edit"
note "    Access: Service Tokens → Edit"
note "    Access: Organizations, Identity Providers, and Groups → Read"
note "    Account Analytics → Read"
note "    and for counting/freeing seats: whichever of 'Access: Users' or"
note "    'Zero Trust' the picker offers → Edit (names vary; the check below will tell)"
step "Account Resources: Include → your account. TTL: end it a week from today."
step "Continue to summary → Create Token → copy it."
ask_secret CK_API_TOKEN "Paste the token (hidden):"
write_env CK_API_TOKEN "$CK_API_TOKEN"
say "Checking what the token can reach..."
until ck_preflight; do
  note "Org and Users fail until a Zero Trust org exists (next stage). That's fine."
  want "Edit the token and check again?" || break
  pause "Press Enter once the token is updated"
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Zero Trust organization"
ORG=$(cf GET /access/organizations)
if ! cf_ok "$ORG"; then
  say "No Zero Trust organization yet. Create one on the Free plan."
  open_url "https://one.dash.cloudflare.com/"
  step "Pick a team name, then choose the Free plan (50 users)."
  step "At checkout, read what it says about payment, card authorization or overage."
  ask CK_CHECKOUT_NOTE "In a sentence, what did checkout say about billing beyond the free limits?"
  record check4 "Zero Trust Free checkout billing text" "$CK_CHECKOUT_NOTE"
  pause "Press Enter once the org exists"
  ORG=$(cf GET /access/organizations)
fi
printf '%s\n' "$ORG" > "$RAW/org.json"
if cf_ok "$ORG"; then
  write_env CK_TEAM_DOMAIN "$(jq -r '.result.auth_domain' <<<"$ORG")"
  note "team domain: $CK_TEAM_DOMAIN, created $(jq -r '.result.created_at' <<<"$ORG")"
  record check5 "org created_at (strict service-token mode is default after 2026-10-05)" \
    "$(jq -c '{created_at: .result.created_at}' <<<"$ORG")"
else
  warn "Still can't read the org: $(cf_err "$ORG")"
fi
ask CK_ZT_PLAN "Which Zero Trust plan is the org on? (Free / Pay-as-you-go / other)"
write_env CK_ZT_PLAN "$CK_ZT_PLAN"
record check4 "Zero Trust plan" "$CK_ZT_PLAN"
step "Make sure One-time PIN is an enabled login method:"
note "    Zero Trust → Integrations → Identity providers (older menus: Settings → Authentication)"
pause "Press Enter once One-time PIN is enabled"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Test hostname and your email"
say "Use a new subdomain of your spare domain, e.g. ck16.yourdomain.com."
note "The domain must be on this Cloudflare account. Nothing else should use the subdomain."
ask CK_HOST "Test hostname:"
CK_HOST=${CK_HOST#https://}; CK_HOST=${CK_HOST%%/*}
write_env CK_HOST "$CK_HOST"
APPS=$(cf GET /access/apps)
CLASH=$(jq -r --arg base "${CK_HOST#*.}" '.result[]? | select((.domain // "") | contains($base)) | select(.name | startswith("ck16-") | not) | "    \(.name): \(.domain)"' <<<"$APPS" 2>/dev/null || true)
if [[ -n "$CLASH" ]]; then
  warn "These existing Access apps may cover the test hostname and skew the results:"
  printf '%s\n' "$CLASH"
  confirm "Carry on anyway?" || exit 1
fi
ask CK_TESTER_EMAIL "Your email, for the one-time PIN sign-ins:"
write_env CK_TESTER_EMAIL "$CK_TESTER_EMAIL"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Deploy the throwaway Worker"
say "Creates D1 database ck16-db and Worker ck16-checks on $CK_HOST."
deploy_worker || { warn "Deploy failed. Fix the error above and re-run."; exit 1; }
ask CK_WORKERS_DEV_URL "workers.dev URL (from the deploy output):"
write_env CK_WORKERS_DEV_URL "$CK_WORKERS_DEV_URL"
say "Waiting for $CK_HOST to answer (the certificate can take a few minutes)..."
wait_for / OPEN 600 || warn "The custom domain isn't serving yet; the gate checks will fail until it does."
table_head
probe setup "workers.dev reachable" GET /api/ping none "$CK_WORKERS_DEV_URL"
probe setup "custom domain, no Access yet" GET /secret/
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Access test resources"
if [[ -z "${CK_SVC_CLIENT_SECRET:-}" ]] || ! cf_ok "$(cf GET "/access/service_tokens/${CK_SVC_ID:-none}")"; then
  ck_delete_named service_tokens ck16- >/dev/null || true
  SVC=$(cf POST /access/service_tokens '{"name":"ck16-token","duration":"8760h"}')
  cf_ok "$SVC" || { warn "service token failed: $(cf_err "$SVC")"; exit 1; }
  write_env CK_SVC_ID "$(jq -r '.result.id' <<<"$SVC")"
  write_env CK_SVC_CLIENT_ID "$(jq -r '.result.client_id' <<<"$SVC")"
  write_env CK_SVC_CLIENT_SECRET "$(jq -r '.result.client_secret' <<<"$SVC")"
else
  note "Reusing service token $CK_SVC_ID."
fi
ck_policy_exists "${CK_POL_ALLOW:-}" || write_env CK_POL_ALLOW \
  "$(ck_policy ck16-allow-tester allow "$(jq -nc --arg e "$CK_TESTER_EMAIL" '[{email: {email: $e}}]')")"
ck_policy_exists "${CK_POL_TOKEN:-}" || write_env CK_POL_TOKEN \
  "$(ck_policy ck16-service-auth non_identity "$(jq -nc --arg t "$CK_SVC_ID" '[{service_token: {token_id: $t}}]')")"
ck_policy_exists "${CK_POL_BYPASS:-}" || write_env CK_POL_BYPASS \
  "$(ck_policy ck16-bypass-everyone bypass '[{"everyone": {}}]')"
for v in CK_POL_ALLOW CK_POL_TOKEN CK_POL_BYPASS; do
  [[ -n "${!v}" && "${!v}" != null ]] || { warn "$v wasn't created; see $RAW/"; exit 1; }
done
note "Gated apps use: Allow ($CK_TESTER_EMAIL) + Service Auth (ck16-token). That mix is check 5."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Layout A: whole host gated, Bypass on exactly /"
say "Check 1's open question: can '/' alone be public?"
if want "Run layout A?"; then
  layout_a || warn "Layout A stopped early; whatever it recorded is kept."
  pause "Read the table, then press Enter to remove layout A"
  ck_delete_named apps ck16-A- || true
  wait_for /learn/ OPEN 180 || true
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Layout B: whole host gated, Bypass on /welcome, assets and the form"
if want "Run layout B?"; then
  layout_b || warn "Layout B stopped early; whatever it recorded is kept."
  say ""
  say "Now a real browser sign-in, for checks 2 and 3."
  open_url "https://$CK_HOST/secret/?tag=B-login"
  step "Sign in with the PIN sent to $CK_TESTER_EMAIL. You'll land on 'CK16-MARKER page=secret/index'."
  pause "Press Enter once you see it"
  open_url "https://$CK_HOST/api/echo?tag=B-gated"
  open_url "https://$CK_HOST/api/access-requests?tag=B-bypass"
  pause "Press Enter once both new tabs have loaded"
  B_HITS=$(hits B-)
  record check3 "B: browser visits as logged by the Worker" "$B_HITS"
  jq -r '.[] | "    \(.tag): jwt header=\(.jwt_header) type=\(.jwt_type) cookies=\(.cookie_names)"' <<<"$B_HITS" || true
  pause "Press Enter to remove layout B"
  ck_delete_named apps ck16-B- || true
  wait_for /learn/ OPEN 180 || true
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Layout C: only /learn and /api/* gated"
if want "Run layout C?"; then
  layout_c || warn "Layout C stopped early; whatever it recorded is kept."
  say ""
  say "Browser again. Your layout-B cookie is still in the browser, which is part of the test."
  open_url "https://$CK_HOST/uncovered/echo?tag=C-uncovered-before"
  pause "Press Enter once it has loaded"
  open_url "https://$CK_HOST/learn/?tag=C-login"
  step "Sign in again if asked. You'll land on 'CK16-MARKER page=learn/index'."
  pause "Press Enter once you see it"
  open_url "https://$CK_HOST/api/echo?tag=C-gated"
  open_url "https://$CK_HOST/uncovered/echo?tag=C-uncovered-after"
  open_url "https://$CK_HOST/api/access-requests?tag=C-bypass"
  pause "Press Enter once all three tabs have loaded"
  C_HITS=$(hits C-)
  record check3 "C: browser visits as logged by the Worker" "$C_HITS"
  jq -r '.[] | "    \(.tag): jwt header=\(.jwt_header) type=\(.jwt_type) cookies=\(.cookie_names)"' <<<"$C_HITS" || true
  pause "Press Enter to remove layout C"
  ck_delete_named apps ck16-C- || true
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Check 8: D1 batch() and the per-invocation query limit"
note "Free allows 50 queries per invocation; Paid allows 1,000."
if want "Run the D1 checks?"; then
  d1_checks || warn "D1 checks stopped early."
  pause
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Check 7: do Preview requests count as Worker requests?"
say "Sends 300 requests to a Preview, then 300 to production, and compares analytics."
note "Takes about 7 minutes, mostly waiting for analytics."
if want "Run the Preview check?"; then
  preview_check || warn "Preview check stopped early."
  pause
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Check 4: what happens at the 51st seat"
warn "This fills every free seat on your real Zero Trust org with test sign-ins."
warn "Unconfirmed: Free might bill for overage instead of blocking the 51st login."
note "Each sign-in uses a plus address (you+ck16-1@…) with a PIN sent to your inbox."
note "You can stop at any login with q. Stage 14 frees the test seats."
if confirm "Run the seat test?"; then
  ask CK_SEAT_EMAIL_BASE "Email to plus-address (must accept you+tag@ mail):" || true
  [[ -z "${CK_SEAT_EMAIL_BASE:-}" ]] && CK_SEAT_EMAIL_BASE=$CK_TESTER_EMAIL
  write_env CK_SEAT_EMAIL_BASE "$CK_SEAT_EMAIL_BASE"
  seat_check || warn "Seat test stopped early."
  pause
fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Teardown"
say "Deletes every ck16-* Access app, policy and service token, frees the"
say "+ck16- test seats, and deletes the Preview, the Worker and ck16-db."
note "Results stay in $RESULTS."
if confirm "Tear everything down now?"; then
  teardown || true
else
  SKIPPED+=("Teardown: re-run the wizard and answer y at stage 14")
fi

finish
say "Results: $(pwd)/$RESULTS"
say "Tell Claude the checks are done and it will write them up for #16."
}

run_wizard "$@"; exit
